import os
from google.cloud import documentai


def get_document_client():
    config = {
        "project_id": os.getenv('GOOGLE_CLOUD_PROJECT_ID'),
        "location": os.getenv('GOOGLE_CLOUD_LOCATION'),
        "processor_id": os.getenv('GOOGLE_CLOUD_PROCESSOR_ID')
    }
    return documentai.DocumentProcessorServiceClient(
        client_options={"api_endpoint": f"{config['location']}-documentai.googleapis.com"})

def normalize_response(response):
    normalized_response = {}
    for page in response.document.pages:
        normalized_page = {}
        for element in page.layout:
            if element.type_ == 1:  # LAYOUT_TEXT
                normalized_page['text'] = element.text
            elif element.type_ == 2:  # LAYOUT_TABLE
                normalized_page['table'] = element.table
        normalized_response['pages'].append(normalized_page)
    return normalized_response

import boto3


def translate_text(text, source_lang, target_lang):
    translate = boto3.client('translate')
    response = translate.translate_text(Text=text, SourceLanguageCode=source_lang, TargetLanguageCode=target_lang)
    return response.get('TranslatedText')

import boto3


def check_safety(text):
    comprehend = boto3.client('comprehend')
    response = comprehend.detect_sentiment(Text=text, LanguageCode='en')
    return response.get('Sentiment')

import boto3


def extract_fields(text):
    comprehend = boto3.client('comprehend')
    response = comprehend.detect_entities(Text=text, LanguageCode='en')
    return response.get('Entities')
